// The HEAVY half of the registry — statements, stubs, entry names, testcases,
// editorials — merged onto the light rows from ../problems.ts. Server-only by
// convention: import this from app/practice/[slug]/page.tsx, the routes under
// app/api/practice and the tests, never from a "use client" file, or every
// visitor to the list downloads 48 problems' worth of Python.
//
// The five track files are GENERATED by scripts/practice/gen-content.py,
// which runs a reference implementation and the exact stub text on every
// testcase so `expected` and `got` are computed, never guessed. Edit the
// generator, not the output.
//
// `forClient` is the one door to the browser. It strips what a solver must
// not see — the hidden cases (inputs AND outputs), the editorial, the hints
// past the first — so the RSC payload of a problem page cannot be read for
// answers. The hidden inputs travel later, on submit, through
// app/api/practice/[slug]/cases; the expectations never travel at all.

import type { ClientProblem, Problem, ProblemContent, ProblemMeta, TestCase } from "../types";
import { PROBLEMS, getMeta } from "../problems";
import { FINANCE_CONTENT } from "./finance";
import { QUANT_CONTENT } from "./quant";
import { ML_CONTENT } from "./ml";
import { MATHS_CONTENT } from "./maths";
import { TRADING_CONTENT } from "./trading";

export const PROBLEM_CONTENT: Record<string, ProblemContent> = {
  ...FINANCE_CONTENT,
  ...QUANT_CONTENT,
  ...ML_CONTENT,
  ...MATHS_CONTENT,
  ...TRADING_CONTENT,
};

export function withContent(meta: ProblemMeta): Problem | null {
  const content = PROBLEM_CONTENT[meta.id];
  return content ? { ...meta, ...content } : null;
}

export function getProblem(slug: string): Problem | null {
  const meta = getMeta(slug);
  return meta ? withContent(meta) : null;
}

/** Every problem that has both a row and content — the build's static params. */
export function allProblems(): Problem[] {
  return PROBLEMS.map(withContent).filter((p): p is Problem => p !== null);
}

export function visibleCases(p: Problem): TestCase[] {
  return p.cases.filter((c) => !c.hidden);
}

export function hiddenCases(p: Problem): TestCase[] {
  return p.cases.filter((c) => Boolean(c.hidden));
}

/** The problem as the workspace receives it — an allow-list, so a field
    added to ProblemContent tomorrow cannot leak by default. See the note above. */
export function forClient(p: Problem): ClientProblem {
  return {
    id: p.id,
    num: p.num,
    title: p.title,
    blurb: p.blurb,
    track: p.track,
    difficulty: p.difficulty,
    tags: p.tags,
    minutes: p.minutes,
    ...(p.featured ? { featured: true } : {}),
    ...(p.lock ? { lock: p.lock } : {}),
    ...(p.related ? { related: p.related } : {}),
    entry: p.entry,
    statement: p.statement,
    examples: p.examples,
    constraints: p.constraints,
    firstHint: p.hints[0] ?? null,
    hintCount: p.hints.length,
    hasEditorial: Boolean(p.editorial && p.editorial.length > 0),
    stubs: p.stubs,
    cases: visibleCases(p),
    hiddenCount: hiddenCases(p).length,
  };
}
